const input = $json.body ?? $json;
const isObject = input !== null && typeof input === 'object' && !Array.isArray(input);
const brief = isObject && input.brief && typeof input.brief === 'object' ? input.brief : {};
const errors = [];
if (!isObject) errors.push('Request body must be a JSON object.');
if (input.eventType !== 'lead_persisted') errors.push('Unsupported event type.');
if (input.persistence !== 'saved') errors.push('Only newly saved leads are accepted.');
if (typeof input.leadId !== 'string' || !/^[0-9a-f-]{36}$/i.test(input.leadId)) errors.push('A valid leadId is required.');
if (typeof input.requestId !== 'string' || !/^[0-9a-f-]{36}$/i.test(input.requestId)) errors.push('A valid requestId is required.');
if (typeof brief.statedConcernCategory !== 'string' || !brief.statedConcernCategory.trim()) errors.push('brief.statedConcernCategory is required.');
if (typeof brief.recommendedNextAction !== 'string' || !brief.recommendedNextAction.trim()) errors.push('brief.recommendedNextAction is required.');
if (typeof brief.recommendedNextActionRationale !== 'string' || !brief.recommendedNextActionRationale.trim()) errors.push('brief.recommendedNextActionRationale is required.');
if (typeof input.preferredNextStep !== 'string') errors.push('preferredNextStep is required.');
if (typeof input.counsellingContactConsent !== 'boolean') errors.push('counsellingContactConsent must be a boolean.');
if (errors.length) {
  return [{ json: { valid: false, httpStatus: 400, response: { ok: false, status: 'rejected', errors } } }];
}
const nextStep = input.preferredNextStep;
const consent = input.counsellingContactConsent === true;
let channel = 'Information follow-up for human review';
if (nextStep === 'Request a counselling call' && consent) channel = 'Counselling team review; contact only through an approved, consented process';
if (nextStep === 'Request a counselling call' && !consent) channel = 'Do not initiate counselling contact; request needs consent review';
const draft = `Suggested next action: ${brief.recommendedNextAction}\n\nReason: ${brief.recommendedNextActionRationale}\n\nConcern category: ${brief.statedConcernCategory}\n\nRequested next step: ${nextStep}\n\nReview the approved facts and the student's preferences before any contact.`;
return [{ json: {
  valid: true,
  httpStatus: 200,
  response: {
    ok: true,
    status: 'prepared_for_review',
    leadReferenceId: input.leadId,
    requestId: input.requestId,
    concernCategory: brief.statedConcernCategory,
    recommendedNextAction: brief.recommendedNextAction,
    recommendedNextActionRationale: brief.recommendedNextActionRationale,
    suggestedHandling: channel,
    counsellingContactConsent: consent,
    followUpDraft: draft,
    messageSent: false,
    counsellingBooked: false
  }
} }];
